insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('zolotye-lukovye-kolca-v-pivnom-klyare', 'snack', false, null, 30, 320, 4, 'medium',
   '{"ru":"Золотые луковые кольца в пивном кляре","en":"Golden onion rings in beer batter"}'::jsonb,
   '{"ru":"Хрустящая корочка, воздушное тесто на газировке и сладкий лук внутри — закуска, которая исчезает со стола первой.","en":"A shell that shatters, airy sparkling-water batter and sweet onion inside — the snack that vanishes first."}'::jsonb,
   '{"ru":["Лук крупный — 3 шт","Мука — 120 г","Крахмал — 40 г","Яйцо — 1 шт","Газированная вода — 160 мл","Панировочные сухари — 100 г","Паприка — 1 ч. л.","Сметана — 90 г","Чеснок — 1 зубчик","Петрушка — 8 г","Масло для фритюра — 500 мл","Соль, перец — по вкусу"],"en":["Large onions — 3","Flour — 120 g","Starch — 40 g","Egg — 1","Sparkling water — 160 ml","Breadcrumbs — 100 g","Paprika — 1 tsp","Sour cream — 90 g","Garlic — 1 clove","Parsley — 8 g","Oil for deep-frying — 500 ml","Salt, pepper — to taste"]}'::jsonb,
   '{"ru":["Нарежьте лук кольцами толщиной 1 см и разберите на отдельные кольца.","Смешайте муку, крахмал, яйцо и газированную воду до гладкого кляра, приправьте паприкой, солью и перцем.","Обмакните каждое кольцо в кляр, затем обваляйте в сухарях.","Жарьте в разогретом масле по 2–3 минуты до золотистого цвета, выложите на салфетку.","Смешайте сметану с тёртым чесноком и петрушкой; подавайте кольца горячими с соусом."],"en":["Slice the onions into 1 cm rings and separate them.","Whisk flour, starch, egg and sparkling water into a smooth batter; season with paprika, salt and pepper.","Dip each ring in the batter, then coat in breadcrumbs.","Fry in hot oil 2–3 minutes until golden; drain on paper.","Stir sour cream with grated garlic and parsley; serve the rings hot with the dip."]}'::jsonb,
   '{"ru":["закуски к пиву","жареное","хрустящее"],"en":["beer snacks","fried","crunchy"]}'::jsonb)
on conflict (slug) do update set
