insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('kartofelnye-dolki-s-paprikoy', 'snack', false, null, 40, 280, 4, 'easy',
   '{"ru":"Картофельные дольки с паприкой и чесночным дипом","en":"Paprika potato wedges with garlic dip"}'::jsonb,
   '{"ru":"Запечённые до румяной корочки дольки с копчёной паприкой и прохладный чесночный соус — простая закуска, которая работает всегда.","en":"Wedges roasted to a crisp edge with smoky paprika and a cool garlic dip — a simple snack that always works."}'::jsonb,
   '{"ru":["Картофель — 800 г","Растительное масло — 35 мл","Паприка — 1,5 ч. л.","Сушёный чеснок — 1 ч. л.","Сметана — 100 г","Свежий чеснок — 1 зубчик","Укроп — 15 г","Соль — 1 ч. л.","Перец — по вкусу"],"en":["Potatoes — 800 g","Vegetable oil — 35 ml","Paprika — 1.5 tsp","Dried garlic — 1 tsp","Sour cream — 100 g","Fresh garlic — 1 clove","Dill — 15 g","Salt — 1 tsp","Pepper — to taste"]}'::jsonb,
   '{"ru":["Нарежьте картофель дольками, промойте от лишнего крахмала и обсушите насухо.","Смешайте масло, паприку, сушёный чеснок, соль и перец.","Обваляйте дольки в специях и разложите на противне в один слой.","Запекайте при 200 °C 30 минут до румяной корочки.","Смешайте сметану со свежим чесноком и укропом; подавайте дип отдельно, чтобы корочка не размокла."],"en":["Cut the potatoes into wedges, rinse off excess starch and pat completely dry.","Mix oil, paprika, dried garlic, salt and pepper.","Coat the wedges and spread on a tray in a single layer.","Roast at 200 °C for 30 minutes until golden.","Stir sour cream with fresh garlic and dill; serve the dip on the side so the crust stays crisp."]}'::jsonb,
   '{"ru":["закуски к пиву","запечённое","картофель"],"en":["beer snacks","baked","potato"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
  minutes = excluded.minutes,
  calories = excluded.calories,
  servings = excluded.servings,
  difficulty = excluded.difficulty,
  title = excluded.title,
  description = excluded.description,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  tags = excluded.tags;

insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('syrnye-palochki-v-dvoynoy-panirovke', 'snack', false, null, 35, 360, 4, 'medium',
   '{"ru":"Сырные палочки в двойной панировке","en":"Double-crumbed cheese sticks"}'::jsonb,
   '{"ru":"Хрустящая оболочка снаружи и тянущийся сыр внутри. Секрет — подморозить сыр и запанировать дважды, чтобы он не вытек.","en":"A crunchy shell outside and molten, stretchy cheese inside. The trick: freeze the cheese and crumb it twice so it never leaks."}'::jsonb,
   '{"ru":["Твёрдый сыр — 300 г","Яйца — 2 шт","Мука — 60 г","Панировочные сухари — 130 г","Паприка — 1/2 ч. л.","Сметана — 90 г","Чеснок — 1 зубчик","Петрушка — 10 г","Масло для фритюра — 400 мл","Соль, перец — по вкусу"],"en":["Hard cheese — 300 g","Eggs — 2","Flour — 60 g","Breadcrumbs — 130 g","Paprika — 1/2 tsp","Sour cream — 90 g","Garlic — 1 clove","Parsley — 10 g","Oil for deep-frying — 400 ml","Salt, pepper — to taste"]}'::jsonb,
   '{"ru":["Нарежьте сыр брусочками и подморозьте 20 минут.","Обваляйте каждый брусочек в муке, затем в яйце и сухарях.","Повторите панировку (яйцо и сухари) второй раз для прочной корочки.","Обжарьте в горячем масле 1–2 минуты до золота и сразу выложите на салфетку.","Смешайте сметану с чесноком и петрушкой; подавайте немедленно, пока сыр тянется."],"en":["Cut the cheese into batons and freeze for 20 minutes.","Coat each baton in flour, then egg and breadcrumbs.","Repeat the egg-and-crumb coat a second time for a sturdy shell.","Fry in hot oil 1–2 minutes until golden and drain at once.","Stir sour cream with garlic and parsley; serve immediately while the cheese pulls."]}'::jsonb,
   '{"ru":["закуски к пиву","сыр","жареное"],"en":["beer snacks","cheese","fried"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
  minutes = excluded.minutes,
